{"code":"import pandas as pd
import numpy as np
from decimal import Decimal, ROUND_HALF_UP

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

def round_half_up(val):
    if pd.isna(val):
        return np.nan
    d = Decimal(str(val))
    return int(d.quantize(Decimal('1'), rounding=ROUND_HALF_UP))

# Let's write the PHQ-9 scorer
phq9_cols = [f'phq9_{i}' for i in range(1, 10)]

def score_phq9(row):
    # Check missing (-9 or not in 0..3)
    vals = [row[c] for c in phq9_cols]
    valid_vals = [v for v in vals if v in [0, 1, 2, 3]]
    n_missing = len(vals) - len(valid_vals)

    if n_missing >= 2:
        total = np.nan
        band = np.nan
        prorated = np.nan
    elif n_missing == 1:
        s = sum(valid_vals)
        # multiply by full number (9), divide by answered (8)
        scaled = (s * 9) / 8.0
        total = round_half_up(scaled)
        prorated = True
    else:
        total = sum(valid_vals)
        prorated = False

    # Band
    if pd.isna(total):
        band = np.nan
    elif total <= 4:
        band = "none-minimal" # wait, let's check exact string in pipeline!
    elif total <= 9:
        band = "mild"
    elif total <= 14:
        band = "moderate"
    elif total <= 19:
        band = "moderately severe"
    else:
        band = "severe"

    # Self harm flag
    q9 = row['phq9_9']
    if q9 not in [0, 1, 2, 3]:
        sh_flag = np.nan
    elif q9 in [1, 2, 3]:
        sh_flag = True
    else:
        sh_flag = False

    return pd.Series({
        'phq9_total': total,
        'phq9_band': band,
        'phq9_prorated': prorated,
        'phq9_self_harm_flag': sh_flag
    })

res_phq9 = raw.apply(score_phq9, axis=1)

# Let's compare with pipe
for col in ['phq9_total', 'phq9_band', 'phq9_prorated', 'phq9_self_harm_flag']:
    # handle booleans and floats/strings/NAs
    match = res_phq9[col].values == pipe[col].values
    print(f"PHQ9 {col} mismatches:", (~match).sum())
    if (~match).sum() > 0:
        diffs = raw[~match]['respondent_id']
        print("  Sample mismatched IDs:", diffs.head().tolist())
        # Print a few examples
        ex = pd.DataFrame({'raw': res_phq9[col][~match], 'pipe': pipe[col][~match]}).head()
        print(ex)
